#!/usr/bin/env python3
"""Build the static library from one catalog. Run from the repository root."""
import json, html
from PIL import Image
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
C=json.loads((ROOT/'data/catalog.json').read_text()); BOOKS=C['books']; V=C['version']; E=html.escape
G=json.loads((ROOT/'assets/gallery/gallery-data.json').read_text())
CATS={'paisagens':'Paisagens','cidades':'Cidades e cotidiano','ruinas':'Ruínas e mistérios','criaturas':'Criaturas','flora':'Flora e fungos','personagens':'Personagens','cenas':'Cenas e aventuras','olhos':'Olhos e manifestações','estudos':'Estudos visuais'}
def cover(name, priority=False, width=180):
 w,h=Image.open(ROOT/'assets/covers/responsive'/f'{name}-520.webp').size
 return f'<img src="assets/covers/responsive/{name}-520.webp" srcset="assets/covers/responsive/{name}-260.webp 260w, assets/covers/responsive/{name}-520.webp 520w" sizes="(max-width:720px) 150px, {width}px" width="{w}" height="{h}" alt="" loading="{"eager" if priority else "lazy"}" decoding="async"'+(' fetchpriority="high"' if priority else '')+'>'
def card(b, priority=False):
 derived=b['category']=='derived';badge='Obra derivada · não canônica' if derived else 'Leitura disponível'
 return f'''<article class="book-card" data-book="{b['id']}" data-category="{b['category']}" data-status="{b['status']}" data-search="{E(b['title']+' '+b['kind']+' '+b['description'],quote=True)}"><a class="book-cover" href="{E(b['url'],quote=True)}" aria-label="Ler {E(b['title'])}">{cover(b['cover'],priority)}</a><div class="book-meta"><span class="book-kind">{E(b['kind'])}</span><h3><a href="{E(b['url'],quote=True)}">{E(b['title'])}</a></h3><span class="badge{' derived' if derived else ''}">{badge}</span><p>{E(b['description'])}</p><span class="book-detail">{E(b['detail'])}</span><div class="book-bottom"><span class="book-detail">{E(b['edition'])}</span><a class="text-link" href="{E(b['url'],quote=True)}">Ler agora →</a></div></div></article>'''
def art(i, hidden=False):
 src=i.get('thumbnail') or i['file'];return f'''<a class="art-card" data-art data-category="{E(i['category'])}" data-title="{E(i['title'],quote=True)}" data-full="{E(i['file'],quote=True)}" href="{E(i['file'],quote=True)}"{' hidden' if hidden else ''}><img src="{E(src,quote=True)}" alt="{E(i.get('alt') or i['title'],quote=True)}" width="{i.get('width',1536)}" height="{i.get('height',1024)}" loading="lazy" decoding="async"><strong>{E(i['title'])}</strong><small>{E(CATS.get(i['category'],i['category']))}</small></a>'''
def nav(active):
 links=[('index.html','Início'),('biblioteca.html','Biblioteca'),('atlas.html','Atlas'),('galeria.html','Galeria'),('ferramentas.html','Ferramentas'),('sobre.html','Sobre')]
 return '<a class="skip-link" href="#mainContent">Pular para o conteúdo</a><header class="site-header" id="siteHeader"><div class="wrap nav"><a class="brand" href="index.html">Biblioteca Lumyrieliana</a><button class="menu-toggle" id="menuToggle" type="button" aria-controls="siteNav" aria-expanded="false">Menu</button><nav class="nav-links" id="siteNav" aria-label="Navegação principal">'+''.join(f'<a href="{p}"'+(' aria-current="page"' if active==p else '')+f'>{t}</a>' for p,t in links)+'</nav></div></header>'
def page(path,title,desc,body):
 s=f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{E(desc,quote=True)}"><meta name="theme-color" content="#0d0d0b"><meta property="og:type" content="website"><meta property="og:locale" content="pt_BR"><meta property="og:title" content="{E(title,quote=True)}"><meta property="og:description" content="{E(desc,quote=True)}"><title>{E(title) if title=="Biblioteca Lumyrieliana" else E(title)+" · Biblioteca Lumyrieliana"}</title><link rel="stylesheet" href="assets/library.css?v={V}"><link rel="stylesheet" href="assets/support-widget.css"><script defer src="assets/catalog.js?v={V}"></script><script defer src="assets/library.js?v={V}"></script><script defer src="assets/site-config.js?v={V}"></script><script defer src="assets/support-widget.js"></script></head><body data-library-v3 data-page="{path}">{nav(path)}<main id="mainContent">{body}</main><footer class="site-footer"><div class="wrap footer-row"><span>Lumyriel · Criação e autoria de {E(C['author'])}</span><div><a href="feedback.html">Feedback</a><a href="privacy.html">Privacidade</a><button class="support-footer" data-support-project>Apoie o projeto</button></div></div></footer></body></html>'''
 (ROOT/path).write_text(s)
def intro(kicker,title,desc):return f'<div class="wrap page-intro"><span class="eyebrow">{kicker}</span><h1>{title}</h1><p>{desc}</p></div>'
resume='<aside class="resume" id="readingResume" hidden aria-label="Continuar leitura"><div><span class="eyebrow">Sua leitura</span><strong id="resumeTitle"></strong><p id="resumeLabel"></p></div><a class="btn primary" id="resumeLink" href="biblioteca.html">Continuar leitura →</a></aside>'
hero=''.join(f'<a href="{E(BOOKS[i]["url"],quote=True)}" aria-label="Ler {E(BOOKS[i]["title"])}">{cover(BOOKS[i]["cover"],i==0,210 if i==0 else 150)}</a>' for i in [1,0,2])
body=f'''<section class="hero" id="inicio"><div class="wrap hero-grid"><div><span class="eyebrow">Arquivo de Lumyriel</span><h1>Histórias que parecem ter sobrevivido ao próprio mundo.</h1><p>Romances, crônicas e registros de eras diferentes. Encontre sua próxima leitura e conheça os lugares, as criaturas e as histórias de Lumyriel.</p><div class="actions"><a class="btn primary" href="biblioteca.html">Explorar a biblioteca →</a><a class="btn" href="{E(BOOKS[0]['url'],quote=True)}">Começar a ler</a></div><div class="byline">Criação e autoria · {C['author']}</div></div><div><div class="hero-books" aria-label="Leituras em destaque">{hero}</div><p class="hero-caption">Escolha uma capa para abrir o livro.</p></div></div></section><div class="wrap">{resume}</div>
<section class="section" id="biblioteca"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Entre pelas histórias</span><h2>Leituras de Lumyriel</h2></div><a class="text-link" href="biblioteca.html">Ver todos os livros →</a></div><div class="book-grid">{''.join(card(BOOKS[i]) for i in [0,1,4])}</div><p class="results-status">Na biblioteca, livros canônicos e obras derivadas não canônicas têm categorias próprias.</p></div></section>
<section class="section" id="destaque"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Um mundo para percorrer</span><h2>Além das páginas</h2></div></div><div class="route-grid"><article class="route-card"><h3>Atlas de Lumyriel</h3><p>Lugares, paisagens e caminhos reunidos no projeto de cartografia do mundo.</p><a href="atlas.html">Conhecer o Atlas →</a></article><article class="route-card"><h3>Criar um personagem</h3><p>Origem, aparência, cultura, habilidades e história para personagens que pertencem a Lumyriel.</p><a href="character-creator.html">Abrir o criador →</a></article><article class="route-card"><h3>Métodos de criação</h3><p>Construindo Mundos e Narrar Mundos Vivos compartilham métodos de construção e escrita.</p><a href="biblioteca.html?category=derived">Ver obras derivadas →</a></article></div></div></section>
<section class="section" id="artes"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Arquivo visual</span><h2>Uma janela para Lumyriel</h2></div><a class="text-link" href="galeria.html">Explorar as {len(G)} artes →</a></div><div class="art-grid">{''.join(art(G[i]) for i in [0,18,47,74,90,len(G)-1])}</div><p class="results-status">Artes conceituais geradas com inteligência artificial e selecionadas pelo autor.</p></div></section>'''
page('index.html','Biblioteca Lumyrieliana','Leia as histórias de Lumyriel e explore livros, mapas, artes e ferramentas do mundo.',body)
body=intro('Acervo editorial','Biblioteca Lumyrieliana','Histórias e conhecimentos de Lumyriel, com obras derivadas de criação em uma categoria própria.')+f'<div class="wrap">{resume}<div class="search-controls"><label class="field">Disponibilidade<select id="bookStatus"><option value="all">Todas</option><option value="live">Leitura disponível</option><option value="dev">Em desenvolvimento</option></select></label></div><div class="filter-row" aria-label="Categorias de livros">'+''.join(f'<button type="button" class="filter-btn" data-book-filter="{k}" aria-pressed="{str(k=="all").lower()}">{v}</button>' for k,v in [('all','Todos'),('canon','Canônicos'),('derived','Derivados')])+'</div><p class="results-status" id="bookCount" role="status" aria-live="polite">7 obras disponíveis</p><div id="bookResults">'
for k,t,d in [('canon','Livros canônicos','Histórias, registros e obras didáticas sobre o universo de Lumyriel.'),('derived','Obras derivadas','Métodos e reflexões de criação. Estas obras não estabelecem fatos nem regras canônicas de Lumyriel.')]:
 body+=f'<section class="category" data-book-group="{k}" aria-labelledby="heading-{k}"><div class="category-head"><h2 id="heading-{k}">{t}</h2><p>{d}</p></div><div class="book-grid">'+''.join(card(b) for b in BOOKS if b['category']==k)+'</div></section>'
body+='<p class="empty-state" id="bookEmpty" hidden>Nenhuma obra encontrada. Tente outro termo ou altere os filtros.</p></div></div>'
page('biblioteca.html','Biblioteca','Todos os livros de Lumyriel: obras canônicas e derivadas, com busca por título e assunto.',body)
body=intro('Arquivo visual','Paisagens e histórias','Artes aprovadas, organizadas por coleções. Abra uma imagem para vê-la completa.')+'<section class="wrap" id="artes"><p class="gallery-notice">Artes conceituais geradas com inteligência artificial, selecionadas pelo autor. Os títulos expositivos não criam nomes ou acontecimentos canônicos.</p><div id="visualGallery">'
for category,title in CATS.items():
 members=[i for i in G if i['category']==category]
 if members:body+=f'<section class="category" aria-labelledby="collection-{category}"><div class="category-head"><h2 id="collection-{category}">{title}</h2><p>{len(members)} artes</p></div><div class="art-grid">'+''.join(art(i) for i in members)+'</div></section>'
body+='</div></section>'+'<dialog class="lightbox" id="artDialog" aria-labelledby="artDialogTitle"><div class="lightbox-top"><p id="artDialogTitle"></p><button id="artClose" type="button" aria-label="Fechar imagem">Fechar ×</button></div><div class="lightbox-stage"><img id="artFull" alt=""></div><div class="lightbox-bottom"><button id="artPrev" aria-label="Imagem anterior">← Anterior</button><span id="artPosition" aria-live="polite"></span><button id="artNext" aria-label="Próxima imagem">Próxima →</button></div></dialog>'
page('galeria.html','Galeria','Artes aprovadas de Lumyriel, organizadas por coleções.',body)
body=intro('Projeto em desenvolvimento','Atlas de Lumyriel','Lugares, paisagens e caminhos que, parte por parte, compõem o mapa de Lumyriel.')+f'''<section class="wrap section prose"><h2>Um mundo conectado</h2><p>O projeto do Atlas reúne os estudos de terreno, povoamentos e rotas que sustentam os mapas. A construção acontece por regiões, preservando a continuidade entre os recortes.</p><p>O visualizador está em desenvolvimento e, neste momento, possui acesso restrito. Abrir o Atlas pode solicitar a conta autorizada.</p><div class="actions"><a class="btn primary" href="{C['atlasUrl']}">Abrir o visualizador do Atlas ↗</a><a class="btn" href="galeria.html">Explorar as paisagens</a></div></section>'''
page('atlas.html','Atlas','Conheça o projeto de mapas conectados de Lumyriel e acesse o visualizador.',body)
body=intro('Entre no mundo','Ferramentas e projetos','Recursos para construir personagens e acompanhar os próximos caminhos de Lumyriel.')+f'''<div class="wrap"><section class="project" id="criador"><img src="assets/covers/criador-de-personagens.webp" alt="Capa do Criador de Personagens" width="520" height="930" loading="lazy"><div><span class="eyebrow">Ferramenta disponível</span><h2>Criador de Personagens</h2><p>Construa origem, aparência, cultura, crenças, treinamento, equipamentos, limitações e histórico. A competência nasce daquilo que o personagem viveu, aprendeu e consegue sustentar.</p><p>O criador permite guardar o rascunho neste navegador e exportar a ficha.</p><div class="actions"><a class="btn primary" href="character-creator.html">Criar um personagem →</a></div></div></section><section class="project" id="rpg-preview"><img src="assets/covers/lumyriel-rpg.webp" alt="Capa de Lumyriel RPG" width="520" height="930" loading="lazy"><div><span class="eyebrow">Em planejamento e prototipagem</span><h2>Lumyriel RPG</h2><p>Uma experiência single player em desenvolvimento, pensada para conectar o personagem criado no site a campanhas narradas dinamicamente e coerentes com o mundo.</p><p>Integração com o criador, duração de campanha e dificuldade ajustáveis fazem parte da proposta. O jogo ainda não está disponível para jogar.</p></div></section><section class="section" id="rpg-books-roadmap"><h2>Biblioteca do Lumyriel RPG</h2><p class="results-status">Projetos editoriais em desenvolvimento, com capas aprovadas.</p><div class="rpg-grid">'''
for name,file,desc in [('Livro do Mestre','lumyriel-rpg-livro-do-mestre-hq.jpg','Condução de campanhas, cenas e consequências.'),('Guia do Jogador','lumyriel-rpg-guia-do-jogador-hq.jpg','Criação, interpretação e participação no mundo.'),('Bestiário','lumyriel-rpg-bestiario-hq.jpg','Criaturas, comportamento e integração ao jogo.'),('Raças','lumyriel-rpg-racas-hq.jpg','Povos e espécies jogáveis de Lumyriel.')]:
 body+=f'<article><img src="assets/covers/{file}" alt="Capa de Lumyriel RPG — {name}" width="260" height="390" loading="lazy" decoding="async"><h3>{name}</h3><p>{desc}</p><span class="badge derived">Em desenvolvimento</span></article>'
body+='</div></section></div>'
page('ferramentas.html','Ferramentas','Criador de Personagens e projetos do Lumyriel RPG, com seus estados de desenvolvimento.',body)
body=intro('Criação e autoria','De um projeto acadêmico nasceu Lumyriel.','Um universo em desenvolvimento contínuo, com histórias, culturas, eras, mapas e uma memória própria.')+'''<div class="wrap prose"><section id="origem"><h2>Onde tudo começou</h2><p>Este projeto começou durante a disciplina de Stakeholders e Seus Interesses, ministrada pelo professor Emerson Inacio da Silva no primeiro período do curso de Administração da Faculdade FAVOO, em Vilhena, Rondônia.</p><p>O que nasceu como um projeto acadêmico cresceu para muito além da proposta inicial. Lumyriel se tornou um universo em desenvolvimento contínuo, com histórias, culturas, eras, mapas, documentos e uma memória própria que hoje ultrapassa em muito aquilo que eu imaginava quando comecei.</p><p>Criação e autoria: F E G V Santos.</p></section><section id="inspiracoes"><h2>Algumas das raízes de Lumyriel</h2><p>Referências literárias, jogos, história, filosofia e animação ajudam a formular perguntas. As respostas pertencem ao próprio mundo.</p><h3>J. R. R. Tolkien</h3><p>A sensação de que o mundo existia muito antes do protagonista: povos, ruínas, línguas e memórias que não dependem da câmera para existir.</p><h3>Dungeons &amp; Dragons</h3><p>Perguntas sobre viagem, equipamento, instituições, perigos e cotidiano. Lumyriel não importa classes, níveis ou regras de mesa.</p><h3>RuneScape</h3><p>Fontes parciais, documentos, versões concorrentes e acontecimentos com marcas sociais e administrativas.</p><h3>Duna</h3><p>Ambiente, cultura, religião, recursos e política entrelaçados.</p><h3>Animes e mangás</h3><p>Frieren, Fullmetal Alchemist e Mushoku Tensei estão entre as referências para passagem do tempo, aprendizado gradual, consequência e vida cotidiana.</p></section></div>'''
page('sobre.html','Sobre Lumyriel','A origem, a autoria e as referências criativas do universo de Lumyriel.',body)
# Readers and generated pages consume the same catalog; public text stays untouched.
js='/* Generated by scripts/build-library.py from data/catalog.json. */\nwindow.LUMYRIEL_CATALOG = '+json.dumps(C,ensure_ascii=False,separators=(',',':'))+';\nwindow.LUMYRIEL_READER_DATA = Object.fromEntries(window.LUMYRIEL_CATALOG.books.map(b=>[b.id,b.data]));\n'
(ROOT/'assets/catalog.js').write_text(js)
print('Built 6 static pages and shared catalog from',len(BOOKS),'books and',len(G),'arts')
